                 || evaluator.extendsClass(psiClass, "androidx.media.MediaBrowserServiceCompat", true)
                 || evaluator.extendsClass(psiClass, "android.support.v4.media.MediaBrowserServiceCompat", true);

         if (!isMediaBrowserService) {
             return;
