    public Collection<String> getApplicableElements() {
        return Collections.singletonList(SdkConstants.TAG_SERVICE);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String className = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME);
        if (className.isEmpty()) {
            return;
        }

        PsiClass psiClass = context.getClient().findClass(className);
        if (psiClass == null) {
            return;
        }

        JavaEvaluator evaluator = context.getClient().getJavaEvaluator();
        boolean isMediaBrowserService = evaluator.extendsClass(psiClass, "android.service.media.MediaBrowserService", true)
